// Finance Manager Tool - Phase 10
// Handles transaction logging and debt status

const input = $input.first().json.query || $input.first().json.input || '';
const lower = input.toLowerCase();

// Detect command type
let commandType = 'unknown';
if (lower.includes('log') || lower.includes('spent') || lower.includes('paid')) {
  commandType = 'log_transaction';
} else if (lower.includes('debt') || lower.includes('status') || lower.includes('balance')) {
  commandType = 'debt_status';
} else if (lower.includes('summary') || lower.includes('spending')) {
  commandType = 'spending_summary';
}

let response = '';

if (commandType === 'log_transaction') {
  // Parse amount and category
  const amountMatch = input.match(/\$?(\d+(?:\.\d{2})?)/i);
  const amount = amountMatch ? parseFloat(amountMatch[1]) : 0;

  const categories = ['groceries', 'rent', 'utilities', 'transportation', 'entertainment', 'debt', 'coffee', 'food'];
  let category = 'Other';
  for (const cat of categories) {
    if (lower.includes(cat)) {
      category = cat.charAt(0).toUpperCase() + cat.slice(1);
      break;
    }
  }

  const isDebt = lower.includes('debt') || lower.includes('paid off');

  response = `**Transaction Logged** ✅\n\n`;
  response += `• Amount: **$${amount.toFixed(2)}**\n`;
  response += `• Category: ${category}\n`;
  response += isDebt ? `• Type: Debt Payment 💰\n` : '';
  response += `\n**Next step:** ${isDebt ? 'Great progress on debt!' : 'Check spending summary later'}`;

} else if (commandType === 'debt_status') {
  // Mock debt tracking data
  const currentBalance = 58450;
  const monthlyBurnRate = 1550;
  const targetDebt = 0;
  const monthsToPayoff = Math.ceil(currentBalance / monthlyBurnRate);
  const payoffDate = new Date();
  payoffDate.setMonth(payoffDate.getMonth() + monthsToPayoff);
  const progress = ((60000 - currentBalance) / 60000 * 100).toFixed(1);

  response = `**Debt Burn-Down Status**\n\n`;
  response += `💰 Current balance: **$${currentBalance.toLocaleString()}**\n`;
  response += `📉 Monthly burn rate: **$${monthlyBurnRate.toLocaleString()}/month**\n`;
  response += `🎯 Target: **$${targetDebt}**\n`;
  response += `📅 Projected payoff: **${payoffDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}**\n\n`;
  response += `**Progress:** ${progress}% complete\n`;
  const filled = Math.floor(parseFloat(progress) / 10);
  response += `[${'▓'.repeat(filled)}${'░'.repeat(10-filled)}]\n\n`;
  response += `**Next step:** Keep up the momentum!`;

} else if (commandType === 'spending_summary') {
  response = `**Spending Summary (Last 7 Days)**\n\n`;
  response += `Total: **$345**\n\n`;
  response += `Top categories:\n`;
  response += `• Groceries: $120 (3 transactions)\n`;
  response += `• Transportation: $80 (2 transactions)\n`;
  response += `• Entertainment: $45 (1 transaction)\n`;
  response += `... and 2 more\n\n`;
  response += `**Next step:** Review categories to find savings opportunities`;

} else {
  response = `**Finance Manager**\n\nAvailable commands:\n• "Log $50 for groceries" - record transaction\n• "Debt status" - show burn-down progress\n• "Spending summary" - view recent spending\n\n**Next step:** Try one of the commands above`;
}

return {
  json: {
    output: response,
    commandType
  }
};
